UPDATE kapa_official_price
SET wgs84_x = #{wgs84X, jdbcType=VARCHAR},
    wgs84_y = #{wgs84Y, jdbcType=VARCHAR}
WHERE c_year = #{cYear, jdbcType=VARCHAR}
  AND pnu = #{pnu, jdbcType=VARCHAR}
  AND use_yn = 'Y'

UPDATE kapa_standard_price
SET wgs84_x = #{wgs84X, jdbcType=VARCHAR},
    wgs84_y = #{wgs84Y, jdbcType=VARCHAR}
WHERE c_year = #{cYear, jdbcType=VARCHAR}
  AND s_pnu = #{sPnu, jdbcType=VARCHAR}
  AND use_yn = 'Y'
